function getSaveHistoryStorageKey(user = auth.currentUser) {
  const uid = user?.uid;
  if (isAuthenticatedUser(user) && uid) {
    return `${SAVE_HISTORY_STORAGE_KEY}:${uid}`;
  }
  return `${SAVE_HISTORY_STORAGE_KEY}:guest`;
}

function sanitizeSaveHistoryEntry(raw) {
  if (!raw || typeof raw !== 'object') return null;
  const mode = String(raw.mode || '').toLowerCase();
  if (mode !== SAVE_HISTORY_MODE.learn && mode !== SAVE_HISTORY_MODE.memorization && mode !== SAVE_HISTORY_MODE.recite) {
    return null;
  }
  const surah = Number(raw.surah);
  const ayah = Number(raw.ayah);
  if (!Number.isInteger(surah) || !Number.isInteger(ayah) || surah < 1 || ayah < 1) {
    return null;
  }
  const timestamp = Number(raw.timestamp || raw.savedAt || Date.now());
  const source = typeof raw.source === 'string' ? raw.source : mode;
  return {
    id: typeof raw.id === 'string' && raw.id ? raw.id : `${mode}:${surah}:${ayah}:${timestamp}`,
    mode,
    surah,
    ayah,
    source,
    timestamp: Number.isFinite(timestamp) ? timestamp : Date.now()
  };
}

function mergeSaveHistoryEntries(primary = [], secondary = []) {
  const byKey = new Map();
  [...primary, ...secondary].forEach(item => {
    const entry = sanitizeSaveHistoryEntry(item);
    if (!entry) return;
    const key = `${entry.mode}:${entry.surah}:${entry.ayah}`;
    const prev = byKey.get(key);
    if (!prev || entry.timestamp >= prev.timestamp) {
      byKey.set(key, entry);
    }
  });

  return Array.from(byKey.values())
    .sort((a, b) => b.timestamp - a.timestamp)
    .slice(0, SAVE_HISTORY_LIMIT);
}

function readSaveHistoryFromStorage(user = auth.currentUser) {
  const key = getSaveHistoryStorageKey(user);
  try {
    const raw = localStorage.getItem(key);
    const parsed = raw ? JSON.parse(raw) : [];
    if (!Array.isArray(parsed)) return [];
    return mergeSaveHistoryEntries(parsed, []);
  } catch {
    return [];
  }
}

function writeSaveHistoryToStorage(entries, user = auth.currentUser) {
  const key = getSaveHistoryStorageKey(user);
  const normalized = mergeSaveHistoryEntries(entries, []);
  try {
    localStorage.setItem(key, JSON.stringify(normalized));
  } catch (_) {}
  return normalized;
}

function migrateGuestSaveHistoryIfNeeded(user = auth.currentUser) {
  if (!isAuthenticatedUser(user)) return;
  const guestKey = `${SAVE_HISTORY_STORAGE_KEY}:guest`;
  const userKey = getSaveHistoryStorageKey(user);
  if (guestKey === userKey) return;

  let guestEntries = [];
  try {
    const parsed = JSON.parse(localStorage.getItem(guestKey) || '[]');
    guestEntries = Array.isArray(parsed) ? parsed : [];
  } catch {
    guestEntries = [];
  }

  if (!guestEntries.length) return;

  const userEntries = readSaveHistoryFromStorage(user);
  const merged = mergeSaveHistoryEntries(userEntries, guestEntries);
  try {
    localStorage.setItem(userKey, JSON.stringify(merged));
    localStorage.removeItem(guestKey);
  } catch (_) {}
}

function compareMemoAyahRef(a, b) {
  const aSurah = Number(a?.surah) || 0;
  const bSurah = Number(b?.surah) || 0;
  if (aSurah !== bSurah) return aSurah - bSurah;
  return (Number(a?.ayah) || 0) - (Number(b?.ayah) || 0);
}

function isValidMemoAyahRef(ref) {
  const surah = Number(ref?.surah);
  const ayah = Number(ref?.ayah);
  return Number.isInteger(surah) && surah > 0 && Number.isInteger(ayah) && ayah > 0;
}

function normalizeMemoMemorizedKeys(raw) {
  const deduped = new Set();
  (Array.isArray(raw) ? raw : []).forEach(value => {
    const [surah, ayah] = String(value || '').split(':').map(Number);
    if (!isValidMemoAyahRef({ surah, ayah })) return;
    deduped.add(`${surah}:${ayah}`);
  });
  return Array.from(deduped).sort((a, b) => {
    const [sa, aa] = a.split(':').map(Number);
    const [sb, ab] = b.split(':').map(Number);
    if (sa !== sb) return sa - sb;
    return aa - ab;
  });
}

function normalizeMemoAyahMistakes(raw) {
  if (!raw || typeof raw !== 'object') return {};
  const normalized = {};
  Object.entries(raw).forEach(([key, value]) => {
    const [surah, ayah] = String(key || '').split(':').map(Number);
    if (!isValidMemoAyahRef({ surah, ayah })) return;
    const countSource = typeof value === 'number' ? value : value?.count;
    const count = Math.max(0, Math.round(Number(countSource) || 0));
    if (!count) return;
    normalized[`${surah}:${ayah}`] = {
      count,
      lastMistakeAt: Math.max(0, Number(value?.lastMistakeAt) || 0)
    };
  });
  return normalized;
}

function mergeMemoCache(localMemo = {}, remoteMemo = {}) {
  const merged = {
    unlocked: localMemo.unlocked || null,
    listens: { ...(localMemo.listens || {}) },
    memorizedKeys: normalizeMemoMemorizedKeys(localMemo.memorizedKeys),
    lastProgress: localMemo.lastProgress || null,
    lastMemorized: localMemo.lastMemorized || null,
    ayahMistakes: normalizeMemoAyahMistakes(localMemo.ayahMistakes)
  };

  if (isValidMemoAyahRef(remoteMemo?.unlocked)) {
    const currentUnlocked = isValidMemoAyahRef(merged.unlocked)
      ? merged.unlocked
      : { surah: 1, ayah: 1 };
    merged.unlocked = compareMemoAyahRef(remoteMemo.unlocked, currentUnlocked) > 0
      ? remoteMemo.unlocked
      : currentUnlocked;
  }

  if (remoteMemo?.listens && typeof remoteMemo.listens === 'object') {
    Object.entries(remoteMemo.listens).forEach(([key, value]) => {
      const next = Number(value) || 0;
      const prev = Number(merged.listens[key]) || 0;
      if (next > prev) {
        merged.listens[key] = next;
      }
    });
  }

  merged.memorizedKeys = normalizeMemoMemorizedKeys([
    ...merged.memorizedKeys,
    ...normalizeMemoMemorizedKeys(remoteMemo?.memorizedKeys)
  ]);

  if (remoteMemo?.lastProgress) {
    const incomingTs = Number(remoteMemo.lastProgress?.timestamp) || 0;
    const currentTs = Number(merged.lastProgress?.timestamp) || 0;
    if (!merged.lastProgress || incomingTs >= currentTs) {
      merged.lastProgress = remoteMemo.lastProgress;
    }
  }

  if (remoteMemo?.lastMemorized) {
    const incomingTs = Number(remoteMemo.lastMemorized?.timestamp) || 0;
    const currentTs = Number(merged.lastMemorized?.timestamp) || 0;
    if (!merged.lastMemorized || incomingTs >= currentTs) {
      merged.lastMemorized = remoteMemo.lastMemorized;
    }
  }

  Object.entries(normalizeMemoAyahMistakes(remoteMemo?.ayahMistakes)).forEach(([key, value]) => {
    const current = merged.ayahMistakes[key] || { count: 0, lastMistakeAt: 0 };
    merged.ayahMistakes[key] = {
      count: Math.max(Number(current.count) || 0, Number(value?.count) || 0),
      lastMistakeAt: Math.max(
        Number(current.lastMistakeAt) || 0,
        Number(value?.lastMistakeAt) || 0
      )
    };
  });

  return merged;
}

function syncSavedHistoryToDb(entries, user = auth.currentUser) {
  if (!isAuthenticatedUser(user)) return;
  void saveSavedAyahHistory(entries).catch(err => {
    console.warn('[SavedHistory] Failed to sync save history', err);
  });
}

function readLocalJSONSafe(key, fallback) {
  try {
    const raw = localStorage.getItem(key);
    if (!raw) return fallback;
    return JSON.parse(raw);
  } catch {
    return fallback;
  }
}

async function hydrateSavedHistoryFromDb(user = auth.currentUser) {
  if (!isAuthenticatedUser(user)) return;
  try {
    const localEntries = readSaveHistoryFromStorage(user);
    const remoteEntries = await getSavedAyahHistory();
    const merged = mergeSaveHistoryEntries(localEntries, remoteEntries);
    writeSaveHistoryToStorage(merged, user);
    if (merged.length) {
      await saveSavedAyahHistory(merged);
    }
  } catch (err) {
    console.warn('[SavedHistory] Failed to hydrate save history', err);
  }
}

async function hydrateMemorizationCacheFromDb(user = auth.currentUser) {
  if (!isAuthenticatedUser(user)) return;
  try {
    const remoteMemo = await getMemorizationData();
    if (!remoteMemo || typeof remoteMemo !== 'object') return;

    const localMemo = {
      unlocked: readLocalJSONSafe(MEMO_UNLOCKED_KEY, null),
      listens: readLocalJSONSafe(MEMO_LISTENS_KEY, {}),
      memorizedKeys: readLocalJSONSafe(MEMO_MEMORIZED_KEYS_KEY, []),
      lastProgress: readLocalJSONSafe(MEMO_PROGRESS_KEY, null),
      lastMemorized: readLocalJSONSafe(MEMO_LAST_MEMORIZED_KEY, null),
      ayahMistakes: readLocalJSONSafe(MEMO_AYAH_MISTAKES_KEY, {})
    };
    const merged = mergeMemoCache(localMemo, remoteMemo);

    if (merged.unlocked) {
      localStorage.setItem(MEMO_UNLOCKED_KEY, JSON.stringify(merged.unlocked));
    }
    localStorage.setItem(MEMO_LISTENS_KEY, JSON.stringify(merged.listens || {}));
    localStorage.setItem(MEMO_MEMORIZED_KEYS_KEY, JSON.stringify(merged.memorizedKeys || []));
    if (merged.lastProgress) {
      localStorage.setItem(MEMO_PROGRESS_KEY, JSON.stringify(merged.lastProgress));
    }
    if (merged.lastMemorized) {
      localStorage.setItem(MEMO_LAST_MEMORIZED_KEY, JSON.stringify(merged.lastMemorized));
    }
    if (Object.keys(merged.ayahMistakes || {}).length) {
      localStorage.setItem(MEMO_AYAH_MISTAKES_KEY, JSON.stringify(merged.ayahMistakes));
    }
    if (typeof updateMemorizationHeroButton === 'function') {
      updateMemorizationHeroButton();
    }
  } catch (err) {
    console.warn('[MEMO] Failed to hydrate memorization cache', err);
  }
}

function appendSaveHistoryEntry(mode, surah, ayah, options = {}) {
  const entry = sanitizeSaveHistoryEntry({
    mode,
    surah,
    ayah,
    source: options.source || mode,
    timestamp: options.timestamp || Date.now()
  });
  if (!entry) return null;

  const targetUser = options.user || auth.currentUser;
  const existing = readSaveHistoryFromStorage(targetUser);
  const merged = mergeSaveHistoryEntries([entry], existing);
  writeSaveHistoryToStorage(merged, targetUser);
  syncSavedHistoryToDb(merged, targetUser);
  return entry;
}

function formatSaveHistoryModeLabel(mode) {
  if (mode === SAVE_HISTORY_MODE.learn) return 'Learn';
  if (mode === SAVE_HISTORY_MODE.memorization) return 'Memorization';
  if (mode === SAVE_HISTORY_MODE.recite) return 'Recite';
  return 'Saved';
}

function formatSaveHistoryTimestamp(value) {
  const stamp = Number(value);
  if (!Number.isFinite(stamp) || stamp <= 0) return '--';
  try {
    const dt = new Date(stamp);
    const day = dt.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
    const time = dt.toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' });
    return `${day}, ${time}`;
  } catch {
    return '--';
  }
}

function getReciteSavedAyahKey(surah, ayah) {
  const surahNum = Number(surah);
  const ayahNum = Number(ayah);
  if (!Number.isInteger(surahNum) || !Number.isInteger(ayahNum)) return null;
  return `${surahNum}:${ayahNum}`;
}

function syncReciteSavedAyahSet(user = auth.currentUser) {
  const history = readSaveHistoryFromStorage(user);
  const next = new Set();
  history.forEach(entry => {
    if (entry.mode !== SAVE_HISTORY_MODE.recite) return;
    const key = getReciteSavedAyahKey(entry.surah, entry.ayah);
    if (key) next.add(key);
  });
  reciteSavedAyahSet = next;
}

function isReciteAyahSaved(surah, ayah) {
  const key = getReciteSavedAyahKey(surah, ayah);
  return !!key && reciteSavedAyahSet.has(key);
}

function markReciteAyahSaved(surah, ayah) {
  const key = getReciteSavedAyahKey(surah, ayah);
  if (!key) return;
  reciteSavedAyahSet.add(key);
}
