function pushPopupHistory(closeFn) {
  popupHistoryStack.push(closeFn);
  history.pushState({ popup: true }, '');
}

function popPopupHistoryFromChild() {
  if (!popupHistoryStack.length) return;
  popupHistoryStack.pop();
  ignoreNextPopState = true;
  history.back();
}

function closeTopPopupFromBack() {
  const closeFn = popupHistoryStack.pop();
  if (typeof closeFn === 'function') {
    closeFn();
  }
}

window.addEventListener('popstate', () => {
  if (ignoreNextPopState) {
    ignoreNextPopState = false;
    return;
  }
  if (popupHistoryStack.length) {
    closeTopPopupFromBack();
    return;
  }
  if (pendingDuaReturn && !isDuasMode && typeof setDuasMode === 'function') {
    pendingDuaReturn = false;
    setDuasMode(true);
  }
});

function getIframeOrigin(frame) {
  if (!frame?.src) return RAW_ORIGIN;
  try {
    return new URL(frame.src, window.location.href).origin;
  } catch (err) {
    return RAW_ORIGIN;
  }
}

function postToIframe(frame, message) {
  if (!frame?.contentWindow) return;
  const origin = getIframeOrigin(frame);
  frame.contentWindow.postMessage(message, origin === 'null' ? '*' : origin);
}

function postToViewerIframes(message) {
  const viewerFrames = Array.from(document.querySelectorAll('#viewer iframe'));
  viewerFrames.forEach(frame => {
    postToIframe(frame, message);
  });
}

function postToWindow(win, message) {
  if (!win?.postMessage) return;
  win.postMessage(message, LOCAL_ORIGIN);
}

function isKnownIframeSource(source) {
  if (!source) return false;
  const frames = Array.from(document.querySelectorAll('iframe'));
  return frames.some(frame => frame.contentWindow === source);
}

function resolveAppUrl(path) {
  try {
    return new URL(path, window.location.href).toString();
  } catch {
    return path;
  }
}

function clearPendingAyahUiState() {
  document.documentElement.classList.remove('pending-ayah');
  document.body.classList.remove('pending-ayah');
}

function clearLaunchAyahParamsFromUrl() {
  let next;
  try {
    next = new URL(window.location.href);
  } catch {
    return;
  }

  let changed = false;
  ['action', 'surah', 'ayah'].forEach(key => {
    if (next.searchParams.has(key)) {
      next.searchParams.delete(key);
      changed = true;
    }
  });

  if (!changed) return;
  const target = next.toString();
  if (target !== window.location.href) {
    window.history.replaceState({}, '', target);
  }
}

function isMyQuranQuestUrl(urlLike) {
  try {
    const parsed = new URL(urlLike, window.location.href);
    const host = String(parsed.hostname || '').toLowerCase().replace(/^www\./, '');
    return host === MY_QURAN_QUEST_HOST;
  } catch {
    return false;
  }
}

function maybeRouteInAppUrl(urlLike, options = {}) {
  let parsed;
  try {
    parsed = new URL(urlLike, window.location.href);
  } catch {
    return false;
  }

  if (!isMyQuranQuestUrl(parsed.href)) {
    return false;
  }

  const path = String(parsed.pathname || '/').toLowerCase();
  const tab = String(parsed.searchParams.get('tab') || '').toLowerCase();
  const hash = String(parsed.hash || '').toLowerCase();
  const targetSurah = Number(parsed.searchParams.get('surah'));
  const targetAyah = Number(parsed.searchParams.get('ayah'));

  const isDuasTarget = tab === 'duas' || path === '/duas' || path === '/duas/' || hash === '#duas';
  if (isDuasTarget && typeof setDuasMode === 'function') {
    setDuasMode(true);
    return true;
  }

  const isMemoTarget = tab === 'memo' || tab === 'memorization' || path === '/memorization' || path === '/memorization/' || path.endsWith('/memorization.html');
  if (isMemoTarget) {
    const hasAyahTarget =
      Number.isFinite(targetSurah) && targetSurah > 0 &&
      Number.isFinite(targetAyah) && targetAyah > 0;

    if (hasAyahTarget) {
      openMemorizationAyah(targetSurah, targetAyah);
    } else if (typeof setMemorizationMode === 'function') {
      setMemorizationMode(true, { openRoute: 'current' });
    }
    return true;
  }

  if (Number.isFinite(targetSurah) && targetSurah > 0 && Number.isFinite(targetAyah) && targetAyah > 0) {
    openLearnAyah(targetSurah, targetAyah, { mode: 'learning' });
    return true;
  }

  const shouldReload = options.allowReload !== false;
  if (shouldReload) {
    window.location.href = resolveAppUrl(`${parsed.pathname}${parsed.search}${parsed.hash}`);
    return true;
  }

  return false;
}

function bindMyQuranQuestLinkRouting() {
  if (internalLinkRoutingBound) return;
  internalLinkRoutingBound = true;

  document.addEventListener('click', event => {
    const anchor = event.target instanceof Element ? event.target.closest('a[href]') : null;
    if (!anchor) return;

    const href = anchor.getAttribute('href');
    if (!href || href.startsWith('#') || href.startsWith('javascript:')) return;

    const shouldHandle = isMyQuranQuestUrl(href) || href.startsWith('/') || href.startsWith('./') || href.startsWith('../');
    if (!shouldHandle) return;

    if (!maybeRouteInAppUrl(href)) return;

    event.preventDefault();
    event.stopPropagation();
  }, { capture: true });
}

function triggerTabSwitchVibration() {
  if (!navigator?.vibrate) return;
  const now = Date.now();
  if ((now - lastTabVibrationAt) < 140) return;
  lastTabVibrationAt = now;
  navigator.vibrate(22);
}

function ensureAyahLoadingOverlay() {
  if (ayahLoadingOverlayEl) return ayahLoadingOverlayEl;
  const overlay = document.createElement('div');
  overlay.id = 'ayahLoadingOverlay';
  overlay.className = 'ayah-loading-overlay';
  overlay.setAttribute('aria-live', 'polite');
  overlay.innerHTML = `
    <div class="ayah-loading-card">
      <div class="ayah-loading-spinner" aria-hidden="true"></div>
      <div class="ayah-loading-label" data-ayah-loading-label>Taking you into the universe of verses...</div>
      <div class="ayah-loading-ref" data-ayah-loading-ref></div>
    </div>
  `;
  document.body.appendChild(overlay);
  ayahLoadingOverlayEl = overlay;
  return overlay;
}

function hideAyahLoadingOverlay(token = null) {
  if (token !== null && token !== ayahLoadToken) return;
  if (ayahLoadingTimer) {
    clearTimeout(ayahLoadingTimer);
    ayahLoadingTimer = 0;
  }
  if (ayahLoadingGuardTimer) {
    clearTimeout(ayahLoadingGuardTimer);
    ayahLoadingGuardTimer = 0;
  }
  if (!ayahLoadingOverlayEl) return;
  ayahLoadingOverlayEl.classList.remove('is-visible');
  ayahLoadingOverlayEl.setAttribute('aria-hidden', 'true');
}

function showAyahLoadingOverlay(surah, ayah, token) {
  if (ayahLoadingTimer) {
    clearTimeout(ayahLoadingTimer);
    ayahLoadingTimer = 0;
  }
  if (ayahLoadingGuardTimer) {
    clearTimeout(ayahLoadingGuardTimer);
    ayahLoadingGuardTimer = 0;
  }

  const overlay = ensureAyahLoadingOverlay();
  const labelEl = overlay.querySelector('[data-ayah-loading-label]');
  if (labelEl) {
    const surahNum = Number(surah);
    const ayahNum = Number(ayah);
    const seed = (Number.isFinite(surahNum) ? surahNum : 0) + (Number.isFinite(ayahNum) ? ayahNum : 0) + Number(token || 0);
    const idx = Math.abs(seed) % AYAH_LOADING_MESSAGES.length;
    labelEl.textContent = AYAH_LOADING_MESSAGES[idx] || AYAH_LOADING_MESSAGES[0];
  }
  const refEl = overlay.querySelector('[data-ayah-loading-ref]');
  if (refEl) {
    refEl.textContent = Number.isFinite(Number(surah)) && Number.isFinite(Number(ayah))
      ? `Surah ${Number(surah)} - Ayah ${Number(ayah)}`
      : '';
  }

  overlay.classList.add('is-visible');
  overlay.removeAttribute('aria-hidden');

  ayahLoadingGuardTimer = window.setTimeout(() => {
    if (token !== ayahLoadToken) return;
    hideAyahLoadingOverlay(token);
  }, 9000);
}

function settleAyahLoadForToken(token) {
  if (token !== ayahLoadToken) return;
  if (!document.body.classList.contains('reader-mode')) {
    hideAyahLoadingOverlay(token);
    return;
  }
  hideAyahLoadingOverlay(token);
}

function waitForAyahIframeReady(iframe, token) {
  if (!iframe || token !== ayahLoadToken) {
    settleAyahLoadForToken(token);
    return;
  }

  if (iframeReadySet.has(iframe)) {
    requestAnimationFrame(() => settleAyahLoadForToken(token));
    return;
  }

  const onReady = () => {
    iframe.removeEventListener('load', onReady);
    requestAnimationFrame(() => settleAyahLoadForToken(token));
  };

  iframe.addEventListener('load', onReady, { once: true });

  ayahLoadingTimer = window.setTimeout(() => {
    if (token !== ayahLoadToken) return;
    if (iframeReadySet.has(iframe)) {
      settleAyahLoadForToken(token);
      return;
    }
    const centerIframe = ring.cards?.[1]?.querySelector('iframe');
    if (centerIframe && centerIframe !== iframe) {
      waitForAyahIframeReady(centerIframe, token);
    }
  }, 800);
}
function resetRootScrollPosition() {
  window.scrollTo(0, 0);
  document.documentElement.scrollTop = 0;
  document.body.scrollTop = 0;
}

function sendNativeTabSwitch(tab) {
  if (tab !== 'learn' && tab !== 'memo' && tab !== 'duas') return;
  try {
    if (window.ReactNativeWebView?.postMessage) {
      window.ReactNativeWebView.postMessage(
        JSON.stringify({ type: 'NATIVE_TAB_SWITCH', tab })
      );
    }
  } catch (_) {}
}

function sendNativeSaveProgress(surah, ayah) {
  if (!Number.isInteger(surah) || !Number.isInteger(ayah)) return;
  try {
    if (window.ReactNativeWebView?.postMessage) {
      window.ReactNativeWebView.postMessage(
        JSON.stringify({ type: 'SAVE_PROGRESS', surah, ayah })
      );
    }
  } catch (_) {}
}

async function recordDailyStreak(options = {}) {
  const source = options?.source || 'unknown';
  if (isAuthenticatedUser(auth.currentUser)) {
    const result = await recordUserStreak();
    console.log('[STREAK] recordUserStreak', { source, ...result });
    if (result?.updated) {
      try {
        StreakUI.showPopup(result.oldLength, result.newLength);
      } catch (popupErr) {
        console.warn('[STREAK] Failed to show popup after user streak update', popupErr);
      }
    }
    return result;
  }

  const result = recordGuestStreak();
  console.log('[STREAK] recordGuestStreak', { source, ...result });
  if (result?.updated && result?.today) {
    try {
      StreakUI.showPopup(result.oldLength, result.newLength, { date: result.today });
    } catch (popupErr) {
      console.warn('[STREAK] Failed to show popup after guest streak update', popupErr);
    }
    postToWindow(window, {
      type: 'streakUpdate',
      date: result.today
    });
  }
  return result;
}

function sendNativeGoogleSignInRequest() {
  try {
    if (window.ReactNativeWebView?.postMessage) {
      window.ReactNativeWebView.postMessage(
        JSON.stringify({ type: 'NATIVE_GOOGLE_SIGN_IN' })
      );
      return true;
    }
  } catch (_) {}

  return false;
}

function isEditableElement(target) {
  if (!(target instanceof Element)) return false;
  return Boolean(
    target.closest('input, textarea, [contenteditable="true"], .allow-text-select')
  );
}

function enableNativeTouchGuard() {
  // Android WebView should keep native vertical scroll behavior untouched.
  if (!IS_NATIVE_WEBVIEW || IS_ANDROID_WEBVIEW) return;

  const blockIfNotEditable = event => {
    if (isEditableElement(event.target)) return;
    event.preventDefault();
  };

  document.addEventListener('contextmenu', blockIfNotEditable, { capture: true });
  document.addEventListener('selectstart', blockIfNotEditable, { capture: true });
}

function readCurrentGuestStreakCount() {
  try {
    const raw = localStorage.getItem('guestStreakHistory');
    const parsed = JSON.parse(raw || '[]');
    return Array.isArray(parsed) ? parsed.length : 0;
  } catch (_) {
    return 0;
  }
}

function getRenderedStreakCount() {
  const raw = Number.parseInt(D.streakEl?.dataset?.streakCount || '', 10);
  if (Number.isFinite(raw)) return Math.max(0, raw);
  return readCurrentGuestStreakCount();
}

const GOOGLE_SIGN_IN_ICON_SVG = "<svg version=\"1.1\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 48 48\" aria-hidden=\"true\" focusable=\"false\"><path fill=\"#EA4335\" d=\"M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5z\"></path><path fill=\"#4285F4\" d=\"M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z\"></path><path fill=\"#FBBC05\" d=\"M10.53 28.59c-.48-1.45-.76-2.99-.76-4.59s.27-3.14.76-4.59l-7.98-6.19C.92 16.46 0 20.12 0 24c0 3.88.92 7.54 2.56 10.78l7.97-6.19z\"></path><path fill=\"#34A853\" d=\"M24 48c6.48 0 11.93-2.13 15.89-5.81l-7.73-6c-2.15 1.45-4.92 2.3-8.16 2.3-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48z\"></path><path fill=\"none\" d=\"M0 0h48v48H0z\"></path></svg>";

function renderGoogleSignInIcon(className = '') {
  if (!className) return GOOGLE_SIGN_IN_ICON_SVG;
  return GOOGLE_SIGN_IN_ICON_SVG.replace('<svg ', '<svg class="' + className + '" ');
}

function getDrawerGoogleButtonMarkup(isLoading = false) {
  const label = isLoading ? 'Signing in...' : 'Continue with Google';
  const leadingMarkup = isLoading
    ? '<span class="gsi-material-button-spinner" aria-hidden="true"></span>'
    : '<span class="gsi-material-button-icon" aria-hidden="true">' + renderGoogleSignInIcon('gsi-material-button-icon-svg') + '</span>';

  return '<div class="gsi-material-button-state"></div>'
    + '<div class="gsi-material-button-content-wrapper">'
    + leadingMarkup
    + '<span class="gsi-material-button-contents">' + label + '</span>'
    + '<span class="gsi-material-button-hidden" aria-hidden="true">' + label + '</span>'
    + '</div>';
}

function renderDrawerGoogleLoginButton() {
  if (!D.drawerLoginBtn) return;

  const isLoading = nativeGoogleSignInInFlight;
  D.drawerLoginBtn.classList.toggle('is-loading', isLoading);
  D.drawerLoginBtn.disabled = isLoading;
  D.drawerLoginBtn.style.opacity = isLoading ? '0.88' : '';
  D.drawerLoginBtn.style.pointerEvents = isLoading ? 'none' : '';
  D.drawerLoginBtn.setAttribute('aria-label', isLoading ? 'Signing in with Google' : 'Continue with Google');
  if (isLoading) {
    D.drawerLoginBtn.setAttribute('aria-busy', 'true');
  } else {
    D.drawerLoginBtn.removeAttribute('aria-busy');
  }
  D.drawerLoginBtn.innerHTML = getDrawerGoogleButtonMarkup(isLoading);
}

function shouldShowGoogleStreakChip(user = auth.currentUser, streakCount = getRenderedStreakCount()) {
  return !isAuthenticatedUser(user) && Math.max(0, Number(streakCount) || 0) === 0;
}

function renderTopNavStreakChip(streakCount, user = auth.currentUser) {
  if (!D.streakEl) return false;

  const safeCount = Math.max(0, Number(streakCount) || 0);
  const showGoogle = shouldShowGoogleStreakChip(user, safeCount);
  D.streakEl.dataset.streakCount = String(safeCount);

  if (showGoogle) {
    D.streakEl.dataset.streakMode = 'google';
    D.streakEl.classList.add('streak-info-google');
    D.streakEl.classList.toggle('streak-info-loading', nativeGoogleSignInInFlight);
    D.streakEl.setAttribute('role', 'button');
    D.streakEl.setAttribute('tabindex', '0');
    D.streakEl.setAttribute('aria-busy', nativeGoogleSignInInFlight ? 'true' : 'false');
    D.streakEl.setAttribute('aria-label', nativeGoogleSignInInFlight ? 'Signing in with Google' : 'Continue with Google');
    D.streakEl.setAttribute('title', nativeGoogleSignInInFlight ? 'Signing in with Google' : 'Continue with Google');
    D.streakEl.innerHTML = nativeGoogleSignInInFlight
      ? '<span class="streak-google-spinner" aria-hidden="true"></span><span class="streak-google-loading-label">Signing in</span>'
      : '<span class="streak-google-pill-label">Sign in</span><span class="streak-google-mark" aria-hidden="true">' + renderGoogleSignInIcon('streak-google-logo') + '</span>';
    return true;
  }

  const flame = String.fromCodePoint(0x1F525);
  const streakLabel = 'Reading streak ' + safeCount + ' day' + (safeCount === 1 ? '' : 's');
  D.streakEl.dataset.streakMode = 'streak';
  D.streakEl.classList.remove('streak-info-google', 'streak-info-loading');
  D.streakEl.removeAttribute('role');
  D.streakEl.removeAttribute('tabindex');
  D.streakEl.removeAttribute('title');
  D.streakEl.removeAttribute('aria-busy');
  D.streakEl.setAttribute('aria-label', streakLabel);
  D.streakEl.textContent = flame + safeCount;
  return false;
}

window.renderQuranQuestNavStreak = ({ navEl, count }) => {
  if (!navEl) return false;
  if (!D.streakEl && navEl.id === 'streakDisplay') {
    D.streakEl = navEl;
  }
  if (D.streakEl && navEl !== D.streakEl) return false;
  return renderTopNavStreakChip(count);
};

function setNativeGoogleSignInState(isInFlight) {
  nativeGoogleSignInInFlight = Boolean(isInFlight);

  renderDrawerGoogleLoginButton();

  renderTopNavStreakChip(getRenderedStreakCount(), auth.currentUser);
}

async function launchGoogleSignIn(source = 'drawer') {
  if (nativeGoogleSignInInFlight) return;

  setNativeGoogleSignInState(true);
  showInAppToast('Signing in with Google...', '#0a4d68');

  if (IS_NATIVE_WEBVIEW) {
    const requested = sendNativeGoogleSignInRequest();
    if (!requested) {
      setNativeGoogleSignInState(false);
      showInAppToast('Google sign-in is unavailable right now.', '#dc3545');
      return;
    }
    return;
  }

  try {
    const result = await signInWithGoogle();
    if (result === null) {
      showInAppToast('Redirecting to Google sign-in...', '#0a4d68');
      return;
    }
  } catch (err) {
    const code = String(err?.code || '');
    if (code === 'auth/popup-closed-by-user' || code === 'auth/cancelled-popup-request') {
      setNativeGoogleSignInState(false);
      return;
    }

    console.warn('[Auth] Google sign-in failed from', source, err);
    setNativeGoogleSignInState(false);
    showInAppToast('Login failed. Please try again.', '#dc3545');
  }
}

function isTrustedMessage(e) {
  if (!e || !e.origin) return false;
  if (RAW_ORIGIN === 'null') {
    if (e.origin !== 'null') return false;
  } else if (e.origin !== RAW_ORIGIN) {
    return false;
  }
  if (e.source === window) return true;
  return isKnownIframeSource(e.source);
}

async function handleNativeGoogleSignInResult(payload) {
  if (!payload || typeof payload !== 'object') {
    setNativeGoogleSignInState(false);
    showInAppToast('Login failed. Invalid native auth response.', '#dc3545');
    return;
  }

  if (payload.ok !== true) {
    const errorCode = String(payload.errorCode || '');
    const errorMessage =
      typeof payload.message === 'string' && payload.message.trim().length > 0
        ? payload.message.trim()
        : 'Login failed. Please try again.';

    if (errorCode === 'SIGN_IN_CANCELLED') {
      setNativeGoogleSignInState(false);
      return;
    }

    setNativeGoogleSignInState(false);
    showInAppToast(errorMessage, '#dc3545');
    return;
  }

  const idToken = typeof payload.idToken === 'string' ? payload.idToken.trim() : '';
  const accessToken =
    typeof payload.accessToken === 'string' ? payload.accessToken.trim() : '';

  if (!idToken && !accessToken) {
    setNativeGoogleSignInState(false);
    showInAppToast('Login failed. Missing Google token.', '#dc3545');
    return;
  }

  try {
    await signInWithGoogleTokens({ idToken, accessToken });
  } catch (err) {
    console.warn('[Auth] Native Google token sign-in failed', err);
    showInAppToast('Login failed. Please try again.', '#dc3545');
  } finally {
    setNativeGoogleSignInState(false);
  }
}

function attachNativeGoogleSignInBridge() {
  if (!IS_NATIVE_WEBVIEW) return;

  window.__qqHandleNativeGoogleSignIn = payload => {
    handleNativeGoogleSignInResult(payload);
  };

  const pendingPayload = window.__qqPendingNativeGoogleSignInResult;
  if (pendingPayload) {
    window.__qqPendingNativeGoogleSignInResult = null;
    handleNativeGoogleSignInResult(pendingPayload);
  }
}

