        /* ------------------------------------------
          Auto-hide + user interaction hide
          ------------------------------------------ */
        swipeHintAutoHideTimer = window.setTimeout(() => hide('timeout'), 4000);

        swipeHintDismissHandler = event => hide(event?.type || 'interaction');
        ['touchstart', 'wheel', 'mousedown'].forEach(eventName => {
          window.addEventListener(eventName, swipeHintDismissHandler, { once: true, passive: true });
        });
